30	    @Test
31	    public void testGetPostgresqlMatchedIntegerDataType() {
32	        final PostgresqlSchemaCodegen codegen = new PostgresqlSchemaCodegen();
33	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(null, null, null), "INTEGER");
34	
35	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(-128L, 0L, false), "SMALLINT");
36	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(0L, 255L, false), "SMALLINT");
37	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(500L, 100L, null), "SMALLINT");
38	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(500L, 100L, false), "SMALLINT");
39	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(-32768L, 32767L, false), "SMALLINT");
40	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(0L, 65535L, false), "INTEGER");
41	
42	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(-8388608L, 0L, false), "INTEGER");
43	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(0L, 16777215L, false), "INTEGER");
44	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(Long.parseLong(String.valueOf(Integer.MIN_VALUE)),
45	                0L, false), "INTEGER");
46	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(0L,
47	                Long.parseLong(String.valueOf(Integer.MAX_VALUE)), false), "INTEGER");
48	
49	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(0L, 4294967295L, false), "BIGINT");
50	        Assert.assertSame(codegen.getPostgresqlMatchedIntegerDataType(-2147483649L, 0L, false), "BIGINT");
51	    }
52	
53	    @Test
54	    public void testGetPostgresqlMatchedStringDataType() {
55	        final PostgresqlSchemaCodegen codegen = new PostgresqlSchemaCodegen();
56	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(6, 6), "VARCHAR");
57	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(0, 0), "VARCHAR");
58	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(255, 255), "VARCHAR");
59	
60	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(null, 100), "VARCHAR");
61	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(null, 255), "VARCHAR");
62	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(50, 255), "VARCHAR");
63	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(100, 20), "VARCHAR");
64	
65	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(null, null), "TEXT");
66	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(100, null), "TEXT");
67	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(255, null), "TEXT");
68	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(null, 256), "VARCHAR");
69	
70	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(16777215, null), "TEXT");
71	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(16777215, 100), "TEXT");
72	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(null, 16777215), "TEXT");
73	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(100, 16777215), "TEXT");
74	
75	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(16777216, null), "TEXT");
76	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(null, 16777216), "TEXT");
77	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(16777216, 16777216), "TEXT");
78	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(100, 16777216), "TEXT");
79	        Assert.assertSame(codegen.getPostgresqlMatchedStringDataType(100, Integer.MAX_VALUE), "TEXT");
80	    }
81	
82	    @Test
83	    public void testToCodegenPostgresqlDataTypeArgument() {
84	        final PostgresqlSchemaCodegen codegen = new PostgresqlSchemaCodegen();
85	        String strArgument = "HelloWorld";
86	        HashMap<String, Object> strProp = codegen.toCodegenPostgresqlDataTypeArgument(strArgument);
87	        Assert.assertTrue((Boolean) strProp.get("isString"));
88	        Assert.assertFalse((Boolean) strProp.get("isFloat"));
89	        Assert.assertFalse((Boolean) strProp.get("isInteger"));
90	        Assert.assertFalse((Boolean) strProp.get("isNumeric"));
91	        Assert.assertSame(strProp.get("argumentValue"), strArgument);
92	
93	        Integer intArgument = 10;
94	        HashMap<String, Object> intProp = codegen.toCodegenPostgresqlDataTypeArgument(intArgument);
95	        Assert.assertFalse((Boolean) intProp.get("isString"));
96	        Assert.assertFalse((Boolean) intProp.get("isFloat"));
97	        Assert.assertTrue((Boolean) intProp.get("isInteger"));
98	        Assert.assertTrue((Boolean) intProp.get("isNumeric"));
99	        Assert.assertSame(intProp.get("argumentValue"), intArgument);
100	
101	        Double floatArgument = 3.14;
102	        HashMap<String, Object> floatProp = codegen.toCodegenPostgresqlDataTypeArgument(floatArgument);
103	        Assert.assertFalse((Boolean) floatProp.get("isString"));
104	        Assert.assertTrue((Boolean) floatProp.get("isFloat"));
105	        Assert.assertFalse((Boolean) floatProp.get("isInteger"));
106	        Assert.assertTrue((Boolean) floatProp.get("isNumeric"));
107	        Assert.assertSame(floatProp.get("argumentValue"), floatArgument);
108	    }
