112	        final PostgresqlSchemaCodegen codegen = new PostgresqlSchemaCodegen();
113	        HashMap<String, Object> defaultMap = null;
114	        ArrayList<String> intFixture = new ArrayList<String>(Arrays.asList(
115	                "SMALLINT", "INTEGER", "BIGINT"));
116	        for (String intType : intFixture) {
117	            defaultMap = codegen.toCodegenPostgresqlDataTypeDefault("150", intType);
118	            Assert.assertTrue((Boolean) defaultMap.get("isNumeric"));
119	            Assert.assertFalse((Boolean) defaultMap.get("isString"));
120	            Assert.assertFalse((Boolean) defaultMap.get("isKeyword"));
121	            Assert.assertSame(defaultMap.get("defaultValue"), "150");
122	        }
123	
124	        ArrayList<String> dateFixture = new ArrayList<String>(Arrays.asList(
125	                "TIMESTAMP", "DATE"));
126	        for (String dateType : dateFixture) {
127	            defaultMap = codegen.toCodegenPostgresqlDataTypeDefault("2018-08-12", dateType);
128	            Assert.assertFalse((Boolean) defaultMap.get("isNumeric"));
129	            Assert.assertTrue((Boolean) defaultMap.get("isString"));
130	            Assert.assertFalse((Boolean) defaultMap.get("isKeyword"));
131	            Assert.assertSame(defaultMap.get("defaultValue"), "2018-08-12");
132	        }
133	        defaultMap = codegen.toCodegenPostgresqlDataTypeDefault("CURRENT_TIMESTAMP", "TIMESTAMP");
